SRC = [("TTB: Established American Viticultural Areas", "https://www.ttb.gov/wine/established-avas"),
       ("UC Davis Library AVA Digitizing Project", "https://github.com/UCDavisLibrary/ava"),
       ("Federal Register, Paso Robles 11 AVAs final rule (2014)", "https://www.federalregister.gov/documents/2014/10/09/2014-24169"),
       ("Federal Register, San Luis Obispo Coast final rule (2022)", "https://www.federalregister.gov/documents/2022/03/09/2022-05000"),
       ("Federal Register, Contra Costa final rule (2024)", "https://www.federalregister.gov/documents/2024/03/15/2024-05476/establishment-of-the-contra-costa-viticultural-area-and-modification-of-the-san-francisco-bay-and"),
       ("Federal Register, Gabilan Mountains final rule (2022)", "https://www.federalregister.gov/documents/2022/08/15/2022-17508"),
       ("Wikipedia: Judgment of Paris (wine)", "https://en.wikipedia.org/wiki/Judgment_of_Paris_(wine)")]
CC, SB, PR, SBC, SF = "Central Coast", "Santa Barbara County", "Paso Robles", "San Luis Obispo County", "San Francisco Bay"
regions = [
 region("us", CC, 35.9, -121.0, 7.2,
 "Four hundred kilometres of coast where east-west valleys pull the Pacific inland: Pinot Noir, Chardonnay, Rhône blends and mountain Cabernet.",
 "The Central Coast AVA stretches from the San Francisco Bay Area to Santa Barbara County, about 6.8 million acres with roughly 100,000 acres of vines. What unites it is the cold California Current. Where the Coast Ranges run north-south, they block the ocean and the inland valleys bake; where valleys open east-west (the Santa Ynez and Santa Maria valleys, the Salinas Valley funnel from Monterey Bay, the Templeton Gap), fog and wind pour inland and create some of the coolest vineyard climates in California.\n\nThe Central Coast contains Monterey's vast Salinas Valley plantings, the Santa Cruz Mountains' historic estates, Paso Robles with its 11 districts, and Santa Barbara County's cool-climate Pinot Noir and Chardonnay.",
 "Franciscan missions planted vines from San Carlos Borromeo de Carmelo (1770) to Santa Barbara (1786) and San Luis Obispo. In the 19th century Paul Masson and others built the Santa Cruz Mountains' reputation, and in Livermore Charles Wetmore, Carl Wente and James Concannon planted French cuttings in the 1880s. The modern era came in waves: Martin Ray and Dick Graff (Chalone) in the mountains, mass planting of the Salinas Valley in the 1970s, Santa Barbara's Pinot Noir pioneers (Sanford & Benedict, 1971) and the Rhône Rangers of Paso Robles in the 1980s and 1990s. The film Sideways (2004) made Santa Barbara Pinot Noir briefly the most fashionable wine in America.",
 "Geology is extremely varied: granite and limestone in the Gabilan and Santa Lucia ranges, calcareous soils on Paso Robles' west side and in Mt. Harlan, marine sediments and diatomaceous earth in Santa Barbara. Marine air governs everything.",
 "Chardonnay, Pinot Noir, Cabernet Sauvignon, Syrah, Grenache, Mourvèdre, Zinfandel, Sauvignon Blanc, Riesling.",
 "Bright, saline Pinot Noir and Chardonnay; Rhône blends; Paso Robles Cabernet and Zinfandel; mountain Cabernet from the Santa Cruz Mountains.",
 "Central Coast is an umbrella AVA. California's 85 percent AVA rule applies; Paso Robles wines from its districts must also show 'Paso Robles' (state conjunctive labeling law).",
 ["Central Coast", "Santa Cruz Mountains", "Monterey", "Paso Robles", "Santa Barbara County", "San Francisco Bay", "Livermore Valley"], SRC, parent="California"),
 region("us", SB, 34.67, -120.25, 9.2,
 "Where the mountains turn sideways and the Pacific pours in: California's coolest serious Pinot Noir country.",
 "Santa Barbara County's secret is geography. Here the Transverse Ranges run east-west, so the Santa Maria and Santa Ynez valleys open straight onto the Pacific and act as wind tunnels for cold ocean air. The result is a temperature gradient you can drive through: Sta. Rita Hills at the western end, near Lompoc, is as cool as anywhere in California; Ballard Canyon and Los Olivos are moderate; Happy Canyon in the east is warm enough for Cabernet Sauvignon.\n\nThe county has about 15,000 acres of vines and seven AVAs nested inside the Central Coast.",
 "Mission Santa Barbara (1786) and Mission Santa Inés (1804) grew Mission grapes. Modern planting began around 1964 to 1971: Uriel Nielsen planted in the Santa Maria Valley in 1964, and Richard Sanford and Michael Benedict planted Pinot Noir and Chardonnay west of Buellton in 1971, a vineyard that became the founding block of Sta. Rita Hills. Bien Nacido (1973), Au Bon Climat (Jim Clendenen, 1982) and Qupé (Bob Lindquist) followed. Sideways (2004) was filmed here.",
 "Marine sediments, sandy loams and diatomaceous earth in the west; serpentine soils in Happy Canyon; calcareous soils in Ballard Canyon and Los Olivos. Strong afternoon winds and morning fog.",
 "Pinot Noir and Chardonnay in the west; Syrah, Grenache, Sauvignon Blanc, Cabernet Sauvignon toward the east.",
 "Taut, saline Pinot Noir and Chardonnay; peppery Syrah; Bordeaux varieties from Happy Canyon.",
 "Seven AVAs inside the Central Coast AVA; Santa Ynez Valley contains Sta. Rita Hills, Ballard Canyon, Los Olivos District and Happy Canyon of Santa Barbara.",
 ["Santa Maria Valley", "Sta. Rita Hills", "Santa Ynez Valley", "Ballard Canyon", "Los Olivos District", "Happy Canyon of Santa Barbara", "Alisos Canyon"], SRC, parent="Central Coast"),
 region("us", PR, 35.62, -120.70, 9.0,
 "A big, hot, limestone-laced district split in two by Highway 101 and subdivided into 11 AVAs.",
 "Paso Robles is a big AVA, about 610,000 acres with some 40,000 acres of vines and more than 200 wineries. Highway 101 is the cultural divide. The west side, in the Santa Lucia foothills, has calcareous soils, more rainfall and cool air from the Templeton Gap; it grows Rhône varieties, Zinfandel and structured Cabernet. The east side is flatter, hotter and higher-yielding, with alluvial soils and Cabernet Sauvignon and Merlot for larger brands.\n\nIn 2014 TTB split the AVA into 11 districts based on soils, rainfall and temperature. Paso Robles has one of the largest daily temperature swings in California, often 20 degrees Celsius or more between afternoon and night.",
 "Franciscans at Mission San Miguel planted vines in the late 18th century. Zinfandel arrived with Andrew York at York Mountain in 1882 and with Italian families such as the Pesentis and Dusis in the Templeton area. The Polish pianist Ignacy Paderewski planted Zinfandel on his Rancho San Ignacio in the 1910s. The Rhône revival started when Gary Eberle (1970s) and especially Tablas Creek (the Perrins of Château de Beaucastel and Robert Haas, from 1989) imported French clones.",
 "Calcareous shale and limestone on the west side, alluvial and sandy soils on the east, granitic soils in parts of Creston; summer heat moderated by marine air through the Templeton Gap.",
 "Cabernet Sauvignon, Zinfandel, Syrah, Grenache, Mourvèdre, Petite Sirah, Merlot, Roussanne, Viognier.",
 "Ripe Cabernet; powerful Zinfandel; Rhône blends ('GSM') and Châteauneuf-style whites.",
 "Paso Robles AVA plus 11 district AVAs (2014). Wines labeled with a district must also carry 'Paso Robles'.",
 ["Paso Robles", "Adelaida District", "Creston District", "El Pomar District", "Paso Robles Estrella District", "Paso Robles Geneseo District", "Paso Robles Highlands District", "Paso Robles Willow Creek District", "San Juan Creek", "San Miguel District", "Santa Margarita Ranch", "Templeton Gap District"], SRC, parent="Central Coast")]

A = []
A.append(ava("Central Coast", CC, "Umbrella AVA (1985, adjusted 1999, 2006 and 2024) of about 6.8 million acres covering the coastal counties from Contra Costa and Alameda south to Santa Barbara. It is used for multi-county blends and contains famous AVAs from the Santa Cruz Mountains to Sta. Rita Hills.", sub="California", styles=["red", "white", "sparkling"], dom="red", grapes="Chardonnay, Pinot Noir, Cabernet Sauvignon, Syrah, Zinfandel"))
# Bay Area
A.append(ava("San Francisco Bay", SF, "An umbrella AVA (1999) covering the counties around San Francisco Bay, roughly 2,450 square miles at creation, expanded in 2006, 2008 and 2024 (to take in all of the new Contra Costa AVA). It contains Livermore Valley, Santa Clara Valley, Lamorinda, Contra Costa and others and is used for blends from around the Bay.", sub="Central Coast", styles=["red", "white"], dom="red", grapes="Cabernet Sauvignon, Chardonnay, Zinfandel, Petite Sirah"))
A.append(ava("Livermore Valley", SF,
 "One of California's oldest wine districts (AVA 1982, expanded 2006), an east-west valley in Alameda County where cool air from San Francisco Bay flows in each afternoon. Gravelly soils reminded early growers of Graves; Charles Wetmore planted Sémillon and Sauvignon Blanc from Château d'Yquem cuttings in the 1880s, and his Cresta Blanca white won a gold medal at the 1889 Paris Exposition.\n\nCarl Wente (1883) and James Concannon (1883) founded wineries that are still family-run. The Wente clone of Chardonnay, propagated from cuttings Ernest Wente obtained in 1912, is the ancestor of most Chardonnay planted in California. Concannon's Petite Sirah was the first varietal bottling of that grape (1961).",
 sub="San Francisco Bay", styles=["white", "red", "sweet"], dom="red", grapes="Chardonnay, Sauvignon Blanc, Sémillon, Cabernet Sauvignon, Petite Sirah",
 producers=["Wente", "Concannon", "Darcie Kent", "Steven Kent", "Murrieta's Well", "Retzlaff"],
 nerd="Most Chardonnay in California descends from the 'Wente clone', making Livermore the grandmother of the state's most planted white."))
A.append(ava("Santa Clara Valley", SF, "The historic valley (1989) south of San Francisco Bay, now Silicon Valley. In the 19th century it had dozens of wineries, including Paul Masson's and Almaden (founded 1852 by Charles Lefranc), but urban growth erased most vineyards. Vines remain in the south around Gilroy, Morgan Hill and the Hecker Pass.", sub="San Francisco Bay", styles=["red", "white"], dom="red", grapes="Cabernet Sauvignon, Zinfandel, Chardonnay, Grenache", producers=["J. Lohr (origins)", "Guglielmo", "Sarah's Vineyard"], contains=["San Ysidro District"]))
A.append(ava("San Ysidro District", SF, "A small district (1990) on the eastern side of the Santa Clara Valley near Gilroy, cooled by marine air through the Pajaro Gap. It mostly supplies Chardonnay and Pinot Noir to wineries elsewhere.", sub="Santa Clara Valley", styles=["white", "red"], dom="white", grapes="Chardonnay, Pinot Noir, Merlot"))
A.append(ava("Pacheco Pass", SF, "A small AVA (1984) at the pass through the Diablo Range between Santa Clara and San Benito counties. Strong marine winds; a few vineyards on the historic route to the San Joaquin Valley.", sub="San Francisco Bay", styles=["red", "white"], dom="red", grapes="Zinfandel, Cabernet Sauvignon"))
A.append(ava("Lamorinda", SF, "A small, hilly AVA (2016) in western Contra Costa County named for the towns of Lafayette, Moraga and Orinda. Many tiny vineyards (46 covering 139 acres at approval) on the slopes of the Berkeley Hills grow Cabernet Sauvignon, Merlot, Pinot Noir and Chardonnay, cooled by bay fog.", sub="San Francisco Bay", styles=["red", "white"], dom="red", grapes="Cabernet Sauvignon, Merlot, Pinot Noir, Chardonnay"))
A.append(ava("Contra Costa", SF, "A new AVA (2024) of about 167,100 acres in eastern Contra Costa County, around Oakley, Brentwood and Antioch, with at least 60 vineyards on about 1,700 acres. Its treasure is ungrafted, century-old Zinfandel, Mourvèdre (Mataro), Carignan and Petite Sirah on deep, sandy soils where phylloxera never took hold, much of it bought by producers such as Bedrock, Cline, Turley and Ridge.\n\nCreating it required TTB to enlarge both San Francisco Bay and Central Coast so that Contra Costa sits fully inside them.", sub="San Francisco Bay", styles=["red"], dom="red", grapes="Zinfandel, Mourvèdre, Carignan, Petite Sirah", producers=["Cline (origins)", "Bedrock (Evangelho)", "Turley (sourcing)", "Ridge (sourcing)"], nerd="The Evangelho Vineyard in Antioch, planted in the 1890s, grows own-rooted vines in deep sand dunes left by an ancient river delta."))
A.append(ava("Santa Cruz Mountains", CC,
 "One of the first AVAs defined by its mountains (1982): the boundary follows elevation lines on both sides of the range, roughly above 400 feet on the ocean side and 800 feet on the bay side, to take in the slopes rather than the valleys. The range between Silicon Valley and the Pacific has vineyards scattered through redwood and oak forest, many above the fog.\n\nIts history is outsized. Paul Masson made sparkling wine at Saratoga from the 1890s; Martin Ray founded Mount Eden in the 1940s and preached 100 percent varietal wines; Ridge's Monte Bello Cabernet (made under Paul Draper from 1969) placed fifth in the red flight at the 1976 Paris tasting and won the 30th-anniversary rematch outright in 2006. Rhys, Mount Eden and others make thrilling Pinot Noir and Chardonnay.",
 sub="Central Coast", styles=["red", "white"], dom="red", grapes="Cabernet Sauvignon, Pinot Noir, Chardonnay, Merlot, Zinfandel",
 terroir="Steep slopes of fractured Franciscan shale, sandstone and some limestone (Monte Bello); marine influence, fog in the valleys, and the San Andreas fault running through the range.",
 producers=["Ridge Vineyards", "Mount Eden", "Rhys", "Thomas Fogarty", "Bonny Doon (origins)", "David Bruce", "Hallcrest"],
 nerd="Ridge has printed full ingredient lists on its labels since 2011, a direct challenge to secretive winemaking.", contains=["Ben Lomond Mountain"]))
A.append(ava("Ben Lomond Mountain", CC, "A small mountain AVA (1987) inside the Santa Cruz Mountains, on a ridge northwest of Santa Cruz above the fog line, at 120 to 800 m. Sandy soils from granite and limestone; cool Pinot Noir, Chardonnay and Cabernet.", sub="Santa Cruz Mountains", styles=["red", "white"], dom="red", grapes="Pinot Noir, Chardonnay, Cabernet Sauvignon"))
A.append(ava("Monterey", CC, "Large AVA (1984) covering the Salinas Valley and its side valleys. Cold wind blows up the valley from Monterey Bay every afternoon, so the north is among the coolest places in California and yields are high on the flat valley floor; the south around King City is warmer. Monterey is a major source of Chardonnay, Pinot Noir and Riesling for big brands, with a small number of exceptional sites on the benches.", sub="Central Coast", styles=["white", "red"], dom="white", grapes="Chardonnay, Pinot Noir, Riesling, Cabernet Sauvignon, Merlot", contains=["Santa Lucia Highlands", "Arroyo Seco", "Chalone", "Carmel Valley", "San Bernabe", "San Lucas", "Hames Valley", "San Antonio Valley", "Gabilan Mountains"]))
A.append(ava("Santa Lucia Highlands", CC,
 "Terraced benches (1992) on the eastern flank of the Santa Lucia Range, facing east across the Salinas Valley, from about 30 to 370 m. Morning fog and fierce afternoon winds from Monterey Bay give a long, cool season, while the southeast-facing slopes catch the morning sun. The result is dense, dark-fruited, deeply coloured Pinot Noir and rich Chardonnay and Syrah.\n\nThe Pisoni family (Gary Pisoni planted from 1982) and Garys' Vineyard (with Gary Franscioni), Rosella's and Sleepy Hollow are the famous names.",
 sub="Monterey", styles=["red", "white"], dom="red", grapes="Pinot Noir, Chardonnay, Syrah",
 producers=["Pisoni", "Lucia", "Roar", "Talbott", "Morgan", "Siduri (sourcing)"],
 terroir="Gravelly, well-drained alluvial terraces of granitic origin; strong afternoon winds."))
A.append(ava("Arroyo Seco", CC, "An AVA (1983, boundaries adjusted 2006, 2018 and 2021) around the Arroyo Seco river where it emerges from the Santa Lucia Range near Greenfield. The cool eastern section is known for Riesling and Chardonnay grown on 'Greenfield potatoes', rounded river cobbles that store heat. The warmer canyon to the west grows Cabernet and Zinfandel.", sub="Monterey", styles=["white", "red"], dom="white", grapes="Chardonnay, Riesling, Pinot Noir, Cabernet Sauvignon", producers=["J. Lohr (Arroyo Vista)", "Ventana", "Scheid"]))
A.append(ava("Chalone", CC, "A remote, high bench (1982) at about 500 m in the Gavilan (Gabilan) Mountains, under the volcanic spires of Pinnacles National Park. Its limestone and granite soils are rare in California, and vines were first planted here around 1919. Dick Graff bought the property in 1965 and made Chalone's Burgundian Chardonnay and Pinot Noir; its 1974 Chardonnay was third among the whites in Paris in 1976.", sub="Gabilan Mountains", styles=["white", "red"], dom="white", grapes="Chardonnay, Pinot Noir, Chenin Blanc, Pinot Blanc", producers=["Chalone Vineyard"], nerd="Chalone's water had to be trucked up the mountain for years; the Chenin Blanc vines planted in 1919 are among the oldest in California."))
A.append(ava("Carmel Valley", CC, "A narrow valley (1983) running inland from Carmel-by-the-Sea, sheltered from fog at its upper end by the Santa Lucia Range, where vineyards sit at 200 to 600 m. It is warm enough for Cabernet Sauvignon and Merlot; Durney Vineyards (later Heller Estate) planted the first commercial vineyard in 1968.", sub="Monterey", styles=["red", "white"], dom="red", grapes="Cabernet Sauvignon, Merlot, Chardonnay", producers=["Heller Estate", "Boekenoogen", "Joullian"]))
A.append(ava("San Bernabe", CC, "An AVA (2004) defined by one enormous vineyard south of King City in the Salinas Valley, at one time described as the largest contiguous vineyard in the world (more than 5,000 acres, owned by Delicato). Sandy, wind-deposited soils grow a range of varieties for large brands.", sub="Monterey", styles=["red", "white"], dom="red", grapes="Cabernet Sauvignon, Merlot, Chardonnay, Syrah", producers=["Delicato"]))
A.append(ava("San Lucas", CC, "A warm AVA (1987) in the southern Salinas Valley around San Lucas, beyond the reach of most of Monterey Bay's cold afternoon wind. Large vineyards on alluvial benches, some owned by Delicato, which petitioned for it, supply Cabernet Sauvignon, Merlot and Chardonnay to big producers.", sub="Monterey", styles=["red", "white"], dom="red", grapes="Cabernet Sauvignon, Merlot, Chardonnay"))
A.append(ava("Hames Valley", CC, "The southernmost Monterey AVA (1994), a warm inland valley near the San Luis Obispo County line with wide day-night temperature swings. Shallow, rocky soils grow Bordeaux and Rhône varieties, mostly sold to wineries elsewhere in the Central Coast.", sub="Monterey", styles=["red"], dom="red", grapes="Cabernet Sauvignon, Syrah, Merlot"))
A.append(ava("San Antonio Valley", CC, "A remote valley (2006) west of the Salinas Valley in southern Monterey County, near Mission San Antonio de Padua (1771) and the Fort Hunter Liggett army base. Warm days and cold nights; Rhône and Bordeaux varieties and Zinfandel.", sub="Monterey", styles=["red"], dom="red", grapes="Syrah, Cabernet Sauvignon, Zinfandel", producers=["Pierce Ranch"]))
A.append(ava("Gabilan Mountains", CC, "A large mountain AVA (2022) of about 98,000 acres along the Gabilan (Gavilan) Range between the Salinas Valley and San Benito County, defined by elevation, a cooler climate and granitic and limestone soils. It encloses Chalone and Mt. Harlan, but TTB kept those older AVAs as they are.", sub="Central Coast", styles=["red", "white"], dom="red", grapes="Pinot Noir, Chardonnay, Syrah", contains=["Chalone", "Mt. Harlan"]))
A.append(ava("San Benito", CC, "Umbrella AVA (1987) for the winegrowing valleys of San Benito County, east of Monterey across the Gabilan Range, including Cienega Valley, Paicines and Lime Kiln Valley. Almaden once farmed thousands of acres here.", sub="Central Coast", styles=["red", "white"], dom="red", grapes="Pinot Noir, Chardonnay, Zinfandel, Cabernet Sauvignon", contains=["Cienega Valley", "Paicines", "Lime Kiln Valley"]))
A.append(ava("Mt. Harlan", CC,
 "A one-producer mountain AVA (1990) high in the Gabilan Range, about 670 to 790 m, created for Josh Jensen's Calera. After studying in Burgundy, Jensen searched California for limestone and found it on an old lime kiln site here; he planted Pinot Noir from 1975 in named parcels (Selleck, Reed, Jensen, Mills, de Villiers, Ryan).\n\nThe Pinots are lean, mineral and long-lived, and Calera's Viognier was one of the first in America.",
 sub="Gabilan Mountains", styles=["red", "white"], dom="red", grapes="Pinot Noir, Chardonnay, Viognier", producers=["Calera"],
 nerd="Calera means lime kiln in Spanish; the old kiln Jensen found on the mountain told him the limestone he wanted was there."))
A.append(ava("Cienega Valley", CC, "Historic valley (1982) in San Benito County along the San Andreas fault, where vines were planted in the 1850s. William Palmtag and later Almaden made wine here; DeRose Vineyards farms old, own-rooted Zinfandel and Négrette. Limestone and granite soils.", sub="San Benito", styles=["red"], dom="red", grapes="Zinfandel, Pinot Noir, Cabernet Pfeffer, Négrette", producers=["DeRose", "Eden Rift"], nerd="The vineyard sits directly on the San Andreas fault; the creep of the fault slowly bends rows and has cracked the old winery walls.", contains=["Lime Kiln Valley"]))
A.append(ava("Lime Kiln Valley", CC, "A tiny valley (1982) within Cienega Valley, named for lime kilns that once burned local limestone. Old vineyards grow Zinfandel and Mourvèdre on limestone-rich soils.", sub="Cienega Valley", styles=["red"], dom="red", grapes="Zinfandel, Mourvèdre", producers=["Enz Vineyards (historic)"]))
A.append(ava("Paicines", CC, "A small AVA (1982) in San Benito County south of Hollister, petitioned by Almaden, which once planted large vineyards here. Cool breezes; mostly grape-growing for other wineries.", sub="San Benito", styles=["red", "white"], dom="red", grapes="Cabernet Sauvignon, Chardonnay, Merlot"))
# SLO
A.append(ava("San Luis Obispo Coast", SBC, "A coastal AVA (2022) of about 408,500 acres stretching the length of San Luis Obispo County west of the Santa Lucia Range, from the Monterey line to the Santa Maria River. It is cooled directly by the Pacific and encloses the Edna Valley and Arroyo Grande Valley AVAs. Chardonnay, Pinot Noir and Syrah are the focus.", sub="Central Coast", styles=["red", "white"], dom="white", grapes="Chardonnay, Pinot Noir, Syrah, Albariño", producers=["Stolo", "Talley", "Tolosa", "Center of Effort"], match=["SLO Coast"], contains=["Edna Valley", "Arroyo Grande Valley"]))
A.append(ava("Edna Valley", SBC, "A cool, east-west valley (1982) just south of San Luis Obispo city, open to the Pacific through Morro Bay so that fog and wind flow straight in. It has one of the longest growing seasons in California, ideal for Chardonnay with crisp acidity and Pinot Noir. Soils include volcanic plugs (the Nine Sisters) and marine sediments.", sub="San Luis Obispo Coast", styles=["white", "red"], dom="white", grapes="Chardonnay, Pinot Noir, Syrah, Albariño", producers=["Edna Valley Vineyard", "Chamisal", "Tolosa", "Alban (Rhône pioneer)"], nerd="John Alban planted Viognier, Roussanne and Grenache here around 1990; Alban Vineyards bills itself as the first American winery founded exclusively for Rhône varieties."))
A.append(ava("Arroyo Grande Valley", SBC, "A valley (1990) southeast of Edna Valley that grades from cool and foggy near the coast to warmer at its inland end. Talley Vineyards' Rincon and Rosemary's vineyards give fine Pinot Noir and Chardonnay; at the warmer top end, Saucelito Canyon farms Zinfandel planted in 1880.", sub="San Luis Obispo Coast", styles=["red", "white", "sparkling"], dom="red", grapes="Pinot Noir, Chardonnay, Zinfandel", producers=["Talley", "Saucelito Canyon", "Laetitia"]))
A.append(ava("York Mountain", SBC, "A tiny, cool AVA (1983) in the Santa Lucia Range between Paso Robles and the coast, at about 450 m. Andrew York founded a winery here in 1882, one of the oldest in the county; marine air makes it far cooler than Paso Robles, which is why TTB kept it separate.", sub="Central Coast", styles=["red"], dom="red", grapes="Pinot Noir, Zinfandel, Syrah", nerd="York Mountain sits outside the Paso Robles AVA even though it is almost surrounded by it."))
A.append(ava("Paso Robles", PR, "The large Paso Robles AVA (1983, expanded 2009) covers about 610,000 acres and more than 40,000 acres of vines in northern San Luis Obispo County. Hot days, very cold nights and limestone-rich hills on the west side give powerful Cabernet Sauvignon, Zinfandel and Rhône blends. Since 2014 it has been divided into 11 district AVAs.", sub="Central Coast", styles=["red", "white"], dom="red", grapes="Cabernet Sauvignon, Zinfandel, Syrah, Grenache, Mourvèdre, Petite Sirah, Merlot", producers=["Tablas Creek", "Saxum", "L'Aventure", "Justin", "J. Lohr", "Daou", "Turley (Pesenti)", "Linne Calodo"], contains=["Adelaida District", "Creston District", "El Pomar District", "Paso Robles Estrella District", "Paso Robles Geneseo District", "Paso Robles Highlands District", "Paso Robles Willow Creek District", "San Juan Creek", "San Miguel District", "Santa Margarita Ranch", "Templeton Gap District"]))
A.append(ava("Adelaida District", PR, "The northwestern hills of Paso Robles (2014), at 275 to 670 m in the Santa Lucia foothills, with calcareous shale and limestone soils, more rain than the east and cool nights. It is home to Tablas Creek, where the Perrin family of Château de Beaucastel and importer Robert Haas planted French Rhône clones from 1989, and to Justin's Isosceles and Halter Ranch.", sub="Paso Robles", styles=["red", "white"], dom="red", grapes="Syrah, Grenache, Mourvèdre, Roussanne, Cabernet Sauvignon, Zinfandel", producers=["Tablas Creek", "Justin", "Halter Ranch", "Daou", "Adelaida Vineyards", "Villa Creek"]))
A.append(ava("Paso Robles Willow Creek District", PR, "Rolling hills (2014) west of Paso Robles town, with calcareous soils, cool marine air from the Templeton Gap and some of the region's most famous estates. Saxum's James Berry Vineyard, Linne Calodo and L'Aventure make dense, ripe Rhône and Cabernet blends here.", sub="Paso Robles", styles=["red"], dom="red", grapes="Syrah, Grenache, Mourvèdre, Zinfandel, Cabernet Sauvignon", producers=["Saxum", "L'Aventure", "Linne Calodo", "Booker"]))
A.append(ava("Templeton Gap District", PR, "The southwestern corner of Paso Robles (2014), where gaps in the Santa Lucia Range let ocean air and fog reach the vineyards. It is the coolest of the districts, with calcareous soils; Zinfandel has been grown here by Italian families since the early 20th century.", sub="Paso Robles", styles=["red", "white"], dom="red", grapes="Zinfandel, Syrah, Cabernet Sauvignon, Pinot Noir", producers=["Turley (Pesenti Vineyard)", "Castoro", "Peachy Canyon"]))
A.append(ava("Paso Robles Highlands District", PR, "The high, remote southeastern district (2014), at 365 to 610 m, with the largest day-night temperature swings in Paso Robles, low rainfall and sandy alluvial soils. Large vineyards grow Cabernet, Zinfandel and Rhône varieties.", sub="Paso Robles", styles=["red"], dom="red", grapes="Cabernet Sauvignon, Zinfandel, Syrah, Petite Sirah"))
A.append(ava("Paso Robles Estrella District", PR, "Rolling plains (2014) northeast of Paso Robles along the Estrella River, warm and dry with alluvial terraces. Gary Eberle planted Syrah here in the 1970s, among California's first.", sub="Paso Robles", styles=["red"], dom="red", grapes="Cabernet Sauvignon, Syrah, Merlot", producers=["Eberle", "J. Lohr (Estrella)", "Vina Robles"]))
A.append(ava("Paso Robles Geneseo District", PR, "An area of low hills (2014) east of Paso Robles city, with old alluvial terraces, some calcareous soils and moderate warmth, rainfall slightly higher than further east. Bordeaux and Rhône varieties do well, and Cass and Tobin James are among its wineries.", sub="Paso Robles", styles=["red"], dom="red", grapes="Cabernet Sauvignon, Syrah, Petite Sirah", producers=["Cass", "Tobin James"]))
A.append(ava("El Pomar District", PR, "A district (2014) southeast of Templeton on high, old alluvial terraces with calcareous patches, where some marine air from the Templeton Gap still reaches. Moderate temperatures suit Zinfandel, Cabernet Sauvignon and Merlot; the name recalls the El Pomar ('the orchard') land grant.", sub="Paso Robles", styles=["red"], dom="red", grapes="Cabernet Sauvignon, Zinfandel, Merlot"))
A.append(ava("Creston District", PR, "A district (2014) in the southeast of Paso Robles around the hamlet of Creston, in foothills of the La Panza Range at 300 to 600 m. Mixed alluvial and granitic soils, low rainfall and a warm, dry climate grow Cabernet Sauvignon, Zinfandel and Syrah.", sub="Paso Robles", styles=["red"], dom="red", grapes="Cabernet Sauvignon, Zinfandel, Syrah"))
A.append(ava("San Miguel District", PR, "The northern district (2014) around the town and mission of San Miguel Arcángel (1797), warm with alluvial soils along the Salinas and Estrella rivers. Large vineyards for Cabernet and Merlot.", sub="Paso Robles", styles=["red"], dom="red", grapes="Cabernet Sauvignon, Merlot, Syrah"))
A.append(ava("San Juan Creek", PR, "The eastern, hottest and driest of the Paso Robles districts (2014), in the upper Cholame and San Juan Creek valleys, with low rainfall and big vineyards.", sub="Paso Robles", styles=["red"], dom="red", grapes="Cabernet Sauvignon, Merlot, Syrah"))
A.append(ava("Santa Margarita Ranch", PR, "The southernmost Paso Robles district (2014), a single historic ranch near Santa Margarita that was part of the mission lands of San Luis Obispo. Cooler and wetter than most of Paso Robles; large vineyards of Cabernet and Chardonnay.", sub="Paso Robles", styles=["red", "white"], dom="red", grapes="Cabernet Sauvignon, Chardonnay, Syrah"))
# Santa Barbara
A.append(ava("Santa Maria Valley", SB,
 "A wide, funnel-shaped valley (1981, expanded 2010) that opens west to the Pacific, among the first AVAs in California. Morning fog, afternoon wind and a long, cool season (harvests can run into November) give Pinot Noir and Chardonnay with bright acidity and spice.\n\nBien Nacido Vineyard, planted by the Miller family from 1973 on benches above the Santa Maria River, has supplied scores of producers with vineyard-designated fruit; Au Bon Climat and Qupé share a winery on the property.",
 sub="Central Coast", styles=["red", "white"], dom="red", grapes="Pinot Noir, Chardonnay, Syrah",
 producers=["Au Bon Climat", "Bien Nacido Estate", "Cambria", "Foxen", "Byron", "Qupé"]))
A.append(ava("Santa Ynez Valley", SB, "The broad valley AVA (1983) along the Santa Ynez River, running from Lompoc east toward Lake Cachuma, with a strong west-to-east warming gradient. It contains Sta. Rita Hills, Ballard Canyon, Los Olivos District and Happy Canyon, and is used for blends across them.", sub="Central Coast", styles=["red", "white"], dom="red", grapes="Pinot Noir, Chardonnay, Syrah, Sauvignon Blanc, Grenache, Cabernet Sauvignon", producers=["Firestone", "Gainey", "Buttonwood"], contains=["Sta. Rita Hills", "Ballard Canyon", "Los Olivos District", "Happy Canyon of Santa Barbara"]))
A.append(ava("Sta. Rita Hills", SB,
 "The cold western end of the Santa Ynez Valley (2001, expanded 2016), where the Santa Rosa Road and Highway 246 corridors run between hills of sand, clay and diatomaceous earth straight toward the Pacific. It is one of the coolest places in California to grow red grapes, and its Pinot Noirs combine dark fruit with high acidity, herbs and a saline edge; Chardonnay is equally tense.\n\nRichard Sanford and Michael Benedict planted the Sanford & Benedict vineyard in 1971, proving the area could ripen Pinot Noir. The AVA was approved as 'Santa Rita Hills' and shortened to 'Sta. Rita Hills' in 2005 after Chile's Viña Santa Rita objected to the use of its name.",
 sub="Santa Ynez Valley", styles=["red", "white", "sparkling"], dom="red", grapes="Pinot Noir, Chardonnay, Syrah",
 producers=["Sanford", "Sea Smoke", "Domaine de la Côte", "Sandhi", "Brewer-Clifton", "Melville", "Babcock", "Ken Brown"],
 terroir="Marine sediments, sand, chert and diatomaceous earth; steady afternoon winds; many growing-season days under 25 degrees Celsius.",
 nerd="The 2016 expansion drew 41 objections arguing that the added land sat on a different landmass, a rare public fight over a few hundred acres."))
A.append(ava("Ballard Canyon", SB, "A small, north-south canyon AVA (2013) between Buellton and Los Olivos, with about 7,800 acres. Its growers decided to focus on Syrah, which shows dark fruit and savoury, peppery depth on the canyon's calcareous and sandy soils. Grenache and Sauvignon Blanc also grow well.", sub="Santa Ynez Valley", styles=["red", "white"], dom="red", grapes="Syrah, Grenache, Sauvignon Blanc", producers=["Stolpman", "Beckmen (Purisima Mountain)", "Larner", "Jonata", "Saarloos"]))
A.append(ava("Los Olivos District", SB, "An alluvial plain (2016) of about 22,800 acres around the town of Los Olivos, between Ballard Canyon and Happy Canyon, with 47 vineyards (about 1,120 acres) at approval. Moderate temperatures and well-drained soils suit Sauvignon Blanc, Rhône and Bordeaux varieties.", sub="Santa Ynez Valley", styles=["red", "white"], dom="red", grapes="Sauvignon Blanc, Syrah, Grenache, Cabernet Franc", producers=["Beckmen", "Andrew Murray", "Brander"]))
A.append(ava("Happy Canyon of Santa Barbara", SB, "The eastern and warmest part of the Santa Ynez Valley (2009), a 23,900-acre canyon area with serpentine and rocky soils. Bordeaux varieties ripen here, and Star Lane, Grassini and Happy Canyon Vineyard make Cabernet Sauvignon, Cabernet Franc and Sauvignon Blanc. The name supposedly dates from Prohibition, when moonshine was made in the canyon.", sub="Santa Ynez Valley", styles=["red", "white"], dom="red", grapes="Cabernet Sauvignon, Cabernet Franc, Sauvignon Blanc, Merlot", producers=["Star Lane", "Grassini", "Happy Canyon Vineyard", "Vogelzang"]))
A.append(ava("Alisos Canyon", SB, "A small AVA (2020) of about 5,800 acres in the hills between the Santa Maria and Santa Ynez valleys, near Los Alamos. A cool, foggy marine climate and sandy, calcareous soils suit Syrah and Rhône varieties.", sub="Central Coast", styles=["red", "white"], dom="red", grapes="Syrah, Grenache, Sauvignon Blanc", producers=["Alisos Canyon wineries (Martian Ranch)"]))
S = []
S.append(site("ridge-monte-bello", "us", "Ridge Monte Bello", "vineyard", "Santa Cruz Mountains", 37.3064, -122.1295,
 "Osea Perrone planted on this limestone ridge in the 1880s. Four engineers from the Stanford Research Institute bought the property in 1959 and made their first commercial wine in 1962. Paul Draper's Monte Bello Cabernet placed fifth among the reds at Paris in 1976 and won the rematches of 2006, establishing it as one of the longest-lived wines of the New World.",
 cls="Monte Bello Cabernet: 1st at the 2006 Judgment of Paris rematch", producers=["Ridge Vineyards"]))
S.append(site("mount-eden", "us", "Mount Eden Vineyards", "estate", "Santa Cruz Mountains", 37.2654, -122.0783,
 "Martin Ray, a purist who fought for honest varietal labelling, planted this mountaintop above Saratoga in the 1940s. The estate, run by Jeffrey Patterson since 1981, makes long-lived Chardonnay, Pinot Noir and Cabernet from 'Mount Eden' clones descended from old California selections.", producers=["Mount Eden Vineyards"]))
S.append(site("calera", "us", "Calera (Mt. Harlan)", "estate", "Mt. Harlan", 36.7167, -121.4194,
 "Josh Jensen found limestone and an old lime kiln (calera in Spanish) high in the Gabilan Range and planted Pinot Noir from 1975. Calera's single-parcel Pinots from Mt. Harlan are among California's most Burgundian.", q="approx", producers=["Calera"]))
S.append(site("calera-winery", "us", "Calera Winery (Cienega Road)", "estate", "Cienega Valley", 36.7387, -121.3713,
 "Calera's gravity-flow winery, built in 1977 into the hillside of an old limestone rock-crushing plant on Cienega Road, below its Mt. Harlan vineyards. The terraced building lets grapes and wine move by gravity from level to level, a Burgundian approach Josh Jensen chose before it was fashionable in California.", producers=["Calera"]))
S.append(site("chalone", "us", "Chalone Vineyard", "estate", "Chalone", 36.4701, -121.2299,
 "Vines were first planted on this limestone bench below the Pinnacles around 1919; some Chenin Blanc from that era survives. Dick Graff's Chalone made some of California's first Burgundian Chardonnays; the 1974 placed third among the whites at Paris in 1976.", producers=["Chalone Vineyard"]))
S.append(site("pisoni", "us", "Pisoni Vineyards", "vineyard", "Santa Lucia Highlands", 36.4462, -121.4327,
 "Gary Pisoni planted vines high on the family's cattle ranch in the Santa Lucia Highlands from 1982, using cuttings of disputed Burgundian origin. Pisoni and Garys' Vineyard Pinot Noir made the Highlands famous.", q="approx", producers=["Pisoni", "Lucia", "Siduri"]))
S.append(site("wente", "us", "Wente Vineyards", "estate", "Livermore Valley", 37.6260, -121.7570,
 "Carl H. Wente bought land in Livermore in 1883. In 1912 Ernest Wente is said to have obtained Chardonnay cuttings from the vine nursery at the University of Montpellier; selections from them, the 'Wente clone', became the source of most California Chardonnay. Wente claims the first varietally labelled Chardonnay in America (1936).", q="approx", producers=["Wente"]))
S.append(site("concannon", "us", "Concannon Vineyard", "estate", "Livermore Valley", 37.6630, -121.7380,
 "Irish immigrant James Concannon founded the winery in 1883 and kept it alive through Prohibition with sacramental wine. In 1961 Concannon released the first varietally labelled Petite Sirah in the United States.", q="approx", producers=["Concannon"]))
S.append(site("bien-nacido", "us", "Bien Nacido Vineyard", "vineyard", "Santa Maria Valley", 34.9220, -120.3400,
 "The Miller family planted Bien Nacido ('well born') on old Spanish land-grant benches above the Santa Maria River from 1973. Its blocks are leased to and named by dozens of wineries; Au Bon Climat and Qupé built their shared winery on the property.", q="approx", producers=["Au Bon Climat", "Qupé", "Bien Nacido Estate"]))
S.append(site("sanford-benedict", "us", "Sanford & Benedict Vineyard", "vineyard", "Sta. Rita Hills", 34.6200, -120.3400,
 "Richard Sanford and Michael Benedict planted Pinot Noir and Chardonnay on Santa Rosa Road in 1971, the first vineyard in what became the Sta. Rita Hills. Its own-rooted 1971 blocks still produce, now owned by the Terlato family.", q="approx", producers=["Sanford", "Sandhi", "Au Bon Climat (sourcing)"]))
S.append(site("tablas-creek", "us", "Tablas Creek Vineyard", "estate", "Adelaida District", 35.6364, -120.8597,
 "Founded in 1989 by the Perrin family of Château de Beaucastel and importer Robert Haas, who chose the limestone hills of west Paso Robles. Their imported Rhône clones, quarantined and propagated in their own nursery, went on to supply hundreds of American wineries.", producers=["Tablas Creek"]))
S.append(site("mission-san-antonio", "us", "Mission San Antonio de Padua", "historic", "San Antonio Valley", 36.0155, -121.2483,
 "Founded in 1771, the third California mission. Its restored grist mill and mission-era water system recall the irrigated gardens and vineyards that supplied wine for mass.", cls="Founded 1771", q="approx"))
S.append(site("almaden-cienega", "us", "Old Palmtag-Almaden winery, Cienega Valley", "historic", "Cienega Valley", 36.7480, -121.3830,
 "William Palmtag planted here in the 1850s. The old winery building sits right on the San Andreas fault, whose slow creep (about 1 cm a year) has visibly split the structure, a favourite stop for geologists.", q="approx"))
save_part("p04_central_coast", regions=regions, appellations=A, sites=S)
